// The §4.3 compute residual, made physical: a minimal hand-assembled WASM module (no
// build step — this is the one module that must not link the AssemblyScript runtime at
// all) whose `handle` never returns: 3 pages of memory (room for the 128 KiB scratch,
// §4.1), the scratch global at 8, and an infinite br 0 loop.
export const SPIN_WASM = new Uint8Array([
  0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, // magic + version
  0x01, 0x06, 0x01, 0x60, 0x01, 0x7f, 0x01, 0x7f, // type: (i32) -> (i32)
  0x03, 0x02, 0x01, 0x00,                         // func: 1, type 0
  0x05, 0x05, 0x01, 0x01, 0x03, 0x80, 0x02,       // memory: min 3, max 256
  0x06, 0x06, 0x01, 0x7f, 0x00, 0x41, 0x08, 0x0b, // global i32 = 8
  0x07, 0x1d, 0x03,                               // export: 3
  0x06, 0x6d, 0x65, 0x6d, 0x6f, 0x72, 0x79, 0x02, 0x00, // "memory" . 2 . 0
  0x07, 0x73, 0x63, 0x72, 0x61, 0x74, 0x63, 0x68, 0x03, 0x00, // "scratch" . 3 . 0
  0x06, 0x68, 0x61, 0x6e, 0x64, 0x6c, 0x65, 0x00, 0x00, // "handle" . 0 . 0
  0x0a, 0x0a, 0x01, 0x08,                         // code: 1 body, 8 bytes
  0x00, 0x03, 0x40, 0x0c, 0x00, 0x0b, 0x00, 0x0b, // locals 0; loop { br 0 } end; unreachable; end
]);
